		cx0 = evidence.PaGet(pa, clip, evidence.PfX0())
		cy0 = evidence.PaGet(pa, clip, evidence.PfY0())
		cx1 = evidence.PaGet(pa, clip, evidence.PfX1())
		cy1 = evidence.PaGet(pa, clip, evidence.PfY1())
