func gvNearChord(ax int32, ay int32, bx int32, by int32, px int32, py int32) int32 {
	// 1 when point p lies within GV_FLAT of the chord a-b (the perpendicular distance, in cpt, by the cross product over the
	// chord's longer extent; a degenerate chord is flat when p is near a).
	var dx int32 = bx - ax
	var dy int32 = by - ay
	var span int32 = gvMax(gvAbs(dx), gvAbs(dy))
	if span == 0 {
		if (gvAbs(px-ax) <= gvFlat) && (gvAbs(py-ay) <= gvFlat) {
			return 1
		}
		return 0
	}
	// cross / |chord| with |chord| <= sqrt 2 * len: a distance over this bound is under the true one by at most 41 per cent;
	// the bound is the cheap one the 50 cpt is calibrated to, not a hypot
	var cr int32 = gvAbs((dx * (py - ay)) - (dy * (px - ax)))
	if (cr / span) <= gvFlat {
		return 1
	}
	return 0
}

func gvSubpath(pa *port.Cells, pts *port.Cells, i int32, a int32, b int32, out *port.Cells, flags int32) int32 {
	// The subpath of path i in rows a..b of `pts` (a move and what follows it).
	var fg int32 = evidence.PaGet(pa, i, evidence.PfFlags())
	var filled int32 = fg & evidence.PgFilled()
	var stroked int32 = fg & evidence.PgStroked()
	var lw int32 = evidence.PaGet(pa, i, evidence.PfWidth())
	var n int32 = b - a
	var strokec int32 = evidence.PaGet(pa, i, evidence.PfStroke())
	var dash int32 = evidence.PaGet(pa, i, evidence.PfDash())
	var k int32 = 0
	var op int32 = 0
	var curve int32 = 0
	var thick int32 = 0
	var sx int32 = 0
	var sy int32 = 0
	var px int32 = 0
	var py int32 = 0
	thick = lw
	if thick == 0 {
		thick = gvHair
	}
	// any curve?
	k = 0
	for k < n {
		op = evidence.PtGet(pts, a+k, evidence.PtfOp())
		if op == evidence.PoCurve() {
			curve = 1
		}
		k += 1
	}
	sx = evidence.PtGet(pts, a, evidence.PtfX())
	sy = evidence.PtGet(pts, a, evidence.PtfY())
	// a rectangle: four corners, then (optionally) a line back to the start and/or a close (`re`: a move, three lines, a close; Skia:
	// a move, four lines, a close). `m` is the number of rows that are corners; `closed` says the shape was closed
	if (curve == 0) && (n >= 4) && (n <= 6) {
		var m int32 = n
		var closedr int32 = 0
		var isr int32 = 0
		if evidence.PtGet(pts, a+(m-1), evidence.PtfOp()) == evidence.PoClose() {
			m -= 1
			closedr = 1
		}
		if (m > 4) && ((evidence.PtGet(pts, a+(m-1), evidence.PtfX()) == sx) && (evidence.PtGet(pts, a+(m-1), evidence.PtfY()) == sy)) {
			m -= 1
			closedr = 1
		}
		if m == 4 {
			var x0 int32 = evidence.PtGet(pts, a, evidence.PtfX())
			var y0 int32 = evidence.PtGet(pts, a, evidence.PtfY())
			var x1 int32 = evidence.PtGet(pts, a+1, evidence.PtfX())
			var y1 int32 = evidence.PtGet(pts, a+1, evidence.PtfY())
			var x2 int32 = evidence.PtGet(pts, a+2, evidence.PtfX())
			var y2 int32 = evidence.PtGet(pts, a+2, evidence.PtfY())
			var x3 int32 = evidence.PtGet(pts, a+3, evidence.PtfX())
			var y3 int32 = evidence.PtGet(pts, a+3, evidence.PtfY())
			if (x0 == x1) && ((y1 == y2) && ((x2 == x3) && (y3 == y0))) {
				isr = 1
			}
			if (y0 == y1) && ((x1 == x2) && ((y2 == y3) && (x3 == x0))) {
				isr = 1
			}
			if (isr == 1) && ((closedr == 1) || (filled != 0)) {
				gvRect(pa, i, a, out, gvMin(gvMin(x0, x1), gvMin(x2, x3)), gvMin(gvMin(y0, y1), gvMin(y2, y3)), gvMax(gvMax(x0, x1), gvMax(x2, x3)), gvMax(gvMax(y0, y1), gvMax(y2, y3)), closedr, flags)
				return 0
			}
		}
	}
	// otherwise: straight segments, each a rule when the path is stroked
	if stroked == 0 {
		return 0
	}
	if evidence.PaGet(pa, i, evidence.PfSalpha()) <= 0 {
		return 0
	}
	if thick > gvRuleT {
		return 0
	}
	px = sx
	py = sy
	k = 1
	for k < n {
		op = evidence.PtGet(pts, a+k, evidence.PtfOp())
		if op == evidence.PoLine() {
			gvSegRule(pa, i, a+k, out, px, py, evidence.PtGet(pts, a+k, evidence.PtfX()), evidence.PtGet(pts, a+k, evidence.PtfY()), thick, strokec, gvStyleOf(dash, thick), flags)
			px = evidence.PtGet(pts, a+k, evidence.PtfX())
			py = evidence.PtGet(pts, a+k, evidence.PtfY())
			k += 1
		}
		if op == evidence.PoCurve() {
			// three rows: two control points and the end; flat when both controls are near the chord
			if (k + 2) >= n {
				k = n
			} else {
				var ex int32 = evidence.PtGet(pts, a+(k+2), evidence.PtfX())
				var ey int32 = evidence.PtGet(pts, a+(k+2), evidence.PtfY())
				if (gvNearChord(px, py, ex, ey, evidence.PtGet(pts, a+k, evidence.PtfX()), evidence.PtGet(pts, a+k, evidence.PtfY())) == 1) && (gvNearChord(px, py, ex, ey, evidence.PtGet(pts, a+(k+1), evidence.PtfX()), evidence.PtGet(pts, a+(k+1), evidence.PtfY())) == 1) {
					gvSegRule(pa, i, a+k, out, px, py, ex, ey, thick, strokec, gvStyleOf(dash, thick), flags)
				}
				px = ex
				py = ey
				k += 3
			}
		}
		if op == evidence.PoClose() {
			if (px != sx) || (py != sy) {
				gvSegRule(pa, i, a+k, out, px, py, sx, sy, thick, strokec, gvStyleOf(dash, thick), flags)
			}
			px = sx
			py = sy
			k += 1
		}
		if op == evidence.PoMove() {
			k += 1
		}
	}
	return 0
}

func gvBoxOnly(pa *port.Cells, i int32, out *port.Cells, flags int32) int32 {
	// A path with no geometry kept (truncated, or built by hand): its box, as D179 read every path. The box holds half the stroke,
	// so a stroked one is taken back to the path's own box and read as a rectangle (closed when the path's kind is `rect`).
	var fg int32 = evidence.PaGet(pa, i, evidence.PfFlags())
	var hw int32 = gvSel(fg&evidence.PgStroked(), evidence.PaGet(pa, i, evidence.PfWidth())/2, 0)
	var x0 int32 = evidence.PaGet(pa, i, evidence.PfX0()) + hw
	var y0 int32 = evidence.PaGet(pa, i, evidence.PfY0()) + hw
	var x1 int32 = evidence.PaGet(pa, i, evidence.PfX1()) - hw
	var y1 int32 = evidence.PaGet(pa, i, evidence.PfY1()) - hw
	var closed int32 = 0
	if evidence.PaGet(pa, i, evidence.PfKind()) == evidence.PaRect() {
		closed = 1
	}
	gvRect(pa, i, -1, out, x0, y0, x1, y1, closed, flags)
	return 0
}

func gvPath(pa *port.Cells, pts *port.Cells, mk *port.Cells, i int32, out *port.Cells) int32 {
	// One painted path in `segments` mode.
	var fg int32 = evidence.PaGet(pa, i, evidence.PfFlags())
	var first int32 = evidence.PaGet(pa, i, evidence.PfPfirst())
	var cnt int32 = evidence.PaGet(pa, i, evidence.PfPcount())
	var flags int32 = gvPathFlags(pa, mk, i)
	var start int32 = port.CellsLen(out) / 16
	var a int32 = 0
	var k int32 = 0
	var op int32 = 0
	if (fg & evidence.PgClip()) != 0 {
		return 0
	}
	if ((fg & evidence.PgFilled()) == 0) && ((fg & evidence.PgStroked()) == 0) {
		return 0
	}
	// a shading, a path with no geometry kept or a truncated one: its box
	if ((fg & evidence.PgShading()) != 0) || (((fg & evidence.PgTruncated()) != 0) || ((first < 0) || (cnt <= 0))) {
		if (fg & evidence.PgShading()) != 0 {
			var x0 int32 = evidence.PaGet(pa, i, evidence.PfX0())
			var y0 int32 = evidence.PaGet(pa, i, evidence.PfY0())
			var x1 int32 = evidence.PaGet(pa, i, evidence.PfX1())
			var y1 int32 = evidence.PaGet(pa, i, evidence.PfY1())
			if ((x1 - x0) > gvRuleMin) && ((y1 - y0) > gvRuleMin) {
				if evidence.PaGet(pa, i, evidence.PfFalpha()) > 0 {
					gvSegFill(pa, i, out, x0, y0, x1, y1, -1, flags+glayer.GqfShading())
				}
			}
			return 0
		}
		gvBoxOnly(pa, i, out, flags)
		gvPiecesFinish(out, start)
		return 0
	}
	// the subpaths: from a move to the next move
	a = first
	k = 1
	for k < cnt {
		op = evidence.PtGet(pts, first+k, evidence.PtfOp())
		if op == evidence.PoMove() {
			gvSubpath(pa, pts, i, a, first+k, out, flags)
			a = first + k
		}
		k += 1
	}
	gvSubpath(pa, pts, i, a, first+cnt, out, flags)
	gvPiecesFinish(out, start)
	return 0
}

func gvImageRule(im *port.Cells, j int32, out *port.Cells) int32 {
	// A visible, thin image placement as a rule candidate of colour -1 (`from-image`).
	var x0 int32 = evidence.ImGet(im, j, evidence.MfX0())
	var y0 int32 = evidence.ImGet(im, j, evidence.MfY0())
	var x1 int32 = evidence.ImGet(im, j, evidence.MfX1())
	var y1 int32 = evidence.ImGet(im, j, evidence.MfY1())
	var w int32 = x1 - x0
	var h int32 = y1 - y0
	var page int32 = evidence.ImGet(im, j, evidence.MfPage())
	if evidence.ImGet(im, j, evidence.MfVis()) != 0 {
		return 0
	}
	if (gvMin(w, h) <= gvRuleT) && (gvMax(w, h) >= gvRuleMin) {
		if w >= h {
			gvPush(out, 1, j, -1, page, x0, y0, x1, y1, x0, (y0+y1)/2, x1, (y0+y1)/2, h, -1, evidence.RsSolid(), glayer.GqFromImage())
		} else {
			gvPush(out, 1, j, -1, page, x0, y0, x1, y1, (x0+x1)/2, y0, (x0+x1)/2, y1, w, -1, evidence.RsSolid(), glayer.GqFromImage())
		}
	}
	return 0
}

func GvPage(pa *port.Cells, pts *port.Cells, mk *port.Cells, im *port.Cells, p0 int32, p1 int32, i0 int32, i1 int32, mode int32, out *port.Cells) int32 {
	// The page's candidates (see the head of this file), appended to `out` in paint order; answers how many.
	var before int32 = port.CellsLen(out) / 16
	var i int32 = p0
	var j int32 = i0
	for i < p1 {
		if mode == 0 {
			gvLegacyOne(pa, i, out)
		} else {
			gvPath(pa, pts, mk, i, out)
		}
		i += 1
	}
	if mode == 1 {
		for j < i1 {
			gvImageRule(im, j, out)
			j += 1
		}
	}
	return (port.CellsLen(out) / 16) - before
}
